using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using HarmonyLib;
using RimWorld;
using Verse;

namespace RimMandrake.Minerals
{
    /// <summary>The meteorite whitelist (GENERATED by src/RimMandrake/Utils/gen_mineral_registry.py into Defs/RM_MineralRegistry.xml from
    /// the registry CSV's meteoritic column; never hand-edited). One def, RM_MineralMeteorites.</summary>
    public class RM_MineralMeteoriteDef : Def
    {
        public List<ThingDef> mineables = new List<ThingDef>();
    }

    /// <summary>The meteorite adapter (MINERAL_ADAPTERS_BUILD_DONOR_SOURCES R5; owner card 2026-10-25: only metals and space-ish ores fall
    /// in meteorites, stone types never). Vanilla fills ThingSetMaker_Meteorite.nonSmoothedMineables once per load (Reset, called from
    /// PlayDataLoader before any static constructor) with every mineable; this keeps only the whitelisted ores, and replaces the private
    /// FindRandomMineableDef draw, whose 40% "rock" roll would otherwise pick from an empty set and throw. The master toggle off restores
    /// the vanilla list (re-applied from RM_MineralPolicy.Apply, so a settings change reaches the next meteorite).</summary>
    public static class RM_MineralMeteorite
    {
        public const string WhitelistDef = "RM_MineralMeteorites";

        private static List<ThingDef> vanilla;        // the list as Reset built it, plus anything another mod added after our last write
        private static List<ThingDef> lastWritten;

        public static MeteorFilter Last { get; private set; }
        public static string LastReason { get; private set; } = "never applied";
        public static int Picks { get; private set; }

        public static bool PickPatched
        {
            get
            {
                return RM_MineralQuarry.Owns(AccessTools.Method(typeof(ThingSetMaker_Meteorite), "FindRandomMineableDef"), p => p.Prefixes);
            }
        }

        public static bool ResetPatched
        {
            get { return RM_MineralQuarry.Owns(AccessTools.Method(typeof(ThingSetMaker_Meteorite), nameof(ThingSetMaker_Meteorite.Reset)), p => p.Postfixes); }
        }

        public static HashSet<string> Whitelist()
        {
            var s = new HashSet<string>();
            foreach (RM_MineralMeteoriteDef d in DefDatabase<RM_MineralMeteoriteDef>.AllDefsListForReading)
                if (d.mineables != null) foreach (ThingDef t in d.mineables) if (t != null) s.Add(t.defName);
            return s;
        }

        public static MeteorCandidate Candidate(ThingDef t)
        {
            BuildingProperties b = t.building;
            return new MeteorCandidate(t.defName, b != null && b.isResourceRock, b?.mineableThing != null ? b.mineableThing.BaseMarketValue : 0f);
        }

        public static void AfterReset()
        {
            vanilla = new List<ThingDef>(ThingSetMaker_Meteorite.nonSmoothedMineables);
            lastWritten = null;
            Refresh("ThingSetMaker_Meteorite.Reset");
        }

        public static void Refresh(string why)
        {
            List<ThingDef> live = ThingSetMaker_Meteorite.nonSmoothedMineables;
            if (live == null) return;
            if (vanilla == null) vanilla = new List<ThingDef>(live);     // Reset patch absent or a late first call: adopt what is there
            else if (lastWritten != null)
                foreach (ThingDef t in live) if (t != null && !lastWritten.Contains(t) && !vanilla.Contains(t)) vanilla.Add(t);

            var byName = new Dictionary<string, ThingDef>();
            foreach (ThingDef t in vanilla) if (t != null && !byName.ContainsKey(t.defName)) byName[t.defName] = t;
            // without the draw replacement a stone-free list makes vanilla's rock roll throw: never filter then
            bool enabled = RM_MineralsSettings.enabled && PickPatched;
            MeteorFilter f = RM_MineralMeteoriteKernel.Filter(byName.Values.Select(Candidate).ToList(), Whitelist(), enabled);
            live.Clear();
            foreach (string n in f.Kept) live.Add(byName[n]);
            lastWritten = new List<ThingDef>(live);
            bool changed = Last == null || Last.Active != f.Active || !Last.Kept.SequenceEqual(f.Kept);
            Last = f;
            LastReason = why;
            if (f.FellBack)
                Log.Error("[RM Minerals] meteorite filter (" + why + "): no whitelisted ore (" + WhitelistDef + ") is in the game, so meteorites keep "
                        + "the vanilla list, stone types included");
            else if (RM_MineralsSettings.enabled && !PickPatched)
                Log.Warning("[RM Minerals] meteorite filter NOT active (" + why + "): the FindRandomMineableDef patch is missing, so meteorites keep "
                          + "the vanilla list");
            else if (changed)
                Log.Message("[RM Minerals] meteorites (" + why + "): " + (f.Active ? f.Kept.Count + " ores may fall (" + string.Join(", ", f.Kept)
                          + "), " + f.Dropped.Count + " mineables barred" : "master toggle OFF, vanilla list of " + f.Kept.Count + " restored"));
        }

        /// <summary>The replacement draw; null = let vanilla draw (adapter inactive, or the list is empty).</summary>
        public static ThingDef Pick()
        {
            if (Last == null || !Last.Active) return null;
            List<ThingDef> live = ThingSetMaker_Meteorite.nonSmoothedMineables;
            var cands = new List<MeteorCandidate>();
            var byName = new Dictionary<string, ThingDef>();
            foreach (ThingDef t in live)
            {
                if (t == null || byName.ContainsKey(t.defName)) continue;
                byName[t.defName] = t;
                cands.Add(Candidate(t));
            }
            MeteorCandidate c = RM_MineralMeteoriteKernel.Pick(cands, Rand.Value, Rand.Value);
            if (c == null) return null;
            Picks++;
            return byName[c.DefName];
        }
    }

    [HarmonyPatch(typeof(ThingSetMaker_Meteorite), nameof(ThingSetMaker_Meteorite.Reset))]
    [RimMandrake.Shared.PatchFeature("Meteorites carry only metals and space-ish ores (list)")]
    public static class Patch_MeteoriteReset
    {
        public static void Postfix()
        {
            try { RM_MineralMeteorite.AfterReset(); }
            catch (Exception e) { Log.Error("[RM Minerals] meteorite filter failed, vanilla list kept: " + e); }
        }
    }

    [HarmonyPatch(typeof(ThingSetMaker_Meteorite), "FindRandomMineableDef")]
    [RimMandrake.Shared.PatchFeature("Meteorites carry only metals and space-ish ores (draw)")]
    public static class Patch_MeteoritePick
    {
        public static bool Prefix(ref ThingDef __result)
        {
            ThingDef d = RM_MineralMeteorite.Pick();
            if (d == null) return true;
            __result = d;
            return false;
        }
    }

    /// <summary>Bridge proof hooks for Minerals/validation.py (jawa/static_call).</summary>
    public static class RM_MineralMeteoriteProof
    {
        /// <summary>"reset=0|1;pick=0|1;active=0|1;fellback=0|1;reason=..;whitelist=a,b;list=a,b;stones=N;dropped=N;shares=rock/cheap/precious".
        /// stones counts list entries that are not resource rocks; with active=1 it must be 0.</summary>
        public static string ProofState(string unused)
        {
            MeteorFilter f = RM_MineralMeteorite.Last;
            List<ThingDef> live = ThingSetMaker_Meteorite.nonSmoothedMineables;
            List<MeteorCandidate> c = live.Where(t => t != null).Select(RM_MineralMeteorite.Candidate).ToList();
            float[] s = RM_MineralMeteoriteKernel.BucketShares(c);
            return "reset=" + (RM_MineralMeteorite.ResetPatched ? 1 : 0) + ";pick=" + (RM_MineralMeteorite.PickPatched ? 1 : 0)
                 + ";active=" + (f != null && f.Active ? 1 : 0) + ";fellback=" + (f != null && f.FellBack ? 1 : 0)
                 + ";reason=" + RM_MineralMeteorite.LastReason
                 + ";whitelist=" + string.Join(",", RM_MineralMeteorite.Whitelist().OrderBy(x => x, StringComparer.Ordinal))
                 + ";list=" + string.Join(",", c.Select(x => x.DefName)) + ";stones=" + c.Count(x => !x.ResourceRock)
                 + ";dropped=" + (f == null ? 0 : f.Dropped.Count)
                 + ";shares=" + string.Join("/", s.Select(x => x.ToString("0.###", CultureInfo.InvariantCulture)));
        }

        /// <summary>Generates N meteorites' contents through the real ThingSetMakerDefOf.Meteorite (nothing is spawned) and tallies the
        /// mineable each one is made of: "n=N;picks=P;stones=S;tally=Def:count,..". args = N (default 200, max 2000).</summary>
        public static string ProofSample(string args)
        {
            int n = int.TryParse((args ?? "").Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out int v) ? Math.Max(1, Math.Min(v, 2000)) : 200;
            int before = RM_MineralMeteorite.Picks, stones = 0;
            var tally = new Dictionary<string, int>();
            for (int i = 0; i < n; i++)
            {
                List<Thing> things = ThingSetMakerDefOf.Meteorite.root.Generate();
                Thing first = things.FirstOrDefault();
                string name = first?.def?.defName ?? "(empty)";
                tally[name] = tally.TryGetValue(name, out int k) ? k + 1 : 1;
                if (first?.def?.building != null && !first.def.building.isResourceRock) stones++;
            }
            return "n=" + n + ";picks=" + (RM_MineralMeteorite.Picks - before) + ";stones=" + stones + ";tally="
                 + string.Join(",", tally.OrderByDescending(kv => kv.Value).Select(kv => kv.Key + ":" + kv.Value));
        }

        /// <summary>Re-filters as a settings change would.</summary>
        public static string ProofRefresh(string why)
        {
            RM_MineralMeteorite.Refresh("proof: " + why);
            return ProofState("");
        }
    }
}
